setup:
cat > src/api/policy.ts <<'BENCHEOF'
/**
 * Customer-facing policy surface. The help centre and the mobile app both read
 * this, so it has to agree with the constants it mirrors.
 */
export const POLICY = {
  refundWindowDays: 90,
  sessionTtlHours: 12,
  deliveryTimeoutSeconds: 5,
  supportEmail: "support@orders.example",
};
BENCHEOF

cat >> src/notify/templates.ts <<'BENCHEOF'

/** Shown on the help centre refund page. */
export const refundWindowNotice = () =>
  "You can request a refund within 90 days of your charge.";
BENCHEOF

cat >> src/notify/webhook.ts <<'BENCHEOF'

/** How long a receiver has to acknowledge a delivery. */
export const DELIVERY_TIMEOUT_MS = 5_000;
BENCHEOF

cat > tests/integration/policy.int.test.js <<'BENCHEOF'
import { test } from "node:test";
import assert from "node:assert";
import { readFileSync } from "node:fs";
import { REFUND_WINDOW_DAYS } from "../../src/billing/refund.ts";
import { TOKEN_TTL_HOURS } from "../../src/auth/token.ts";
import { DELIVERY_TIMEOUT_MS } from "../../src/notify/webhook.ts";
import { POLICY } from "../../src/api/policy.ts";
import { refundWindowNotice } from "../../src/notify/templates.ts";

const limits = JSON.parse(readFileSync(new URL("../../config/limits.json", import.meta.url), "utf8"));

test("every copy of the refund window agrees", () => {
  assert.equal(POLICY.refundWindowDays, REFUND_WINDOW_DAYS, "src/api/policy.ts disagrees with src/billing/refund.ts");
  assert.equal(limits.maxChargeAgeMs, REFUND_WINDOW_DAYS * 86_400_000, "config/limits.json maxChargeAgeMs disagrees");
  assert.ok(
    refundWindowNotice().includes(String(REFUND_WINDOW_DAYS)),
    "the customer-facing notice quotes a different number of days",
  );
});

test("every copy of the session lifetime agrees", () => {
  assert.equal(POLICY.sessionTtlHours, TOKEN_TTL_HOURS, "src/api/policy.ts disagrees with src/auth/token.ts");
  assert.equal(
    limits.credentialLifetimeSeconds,
    TOKEN_TTL_HOURS * 3600,
    "config/limits.json credentialLifetimeSeconds disagrees",
  );
});

test("every copy of the delivery timeout agrees", () => {
  assert.equal(
    POLICY.deliveryTimeoutSeconds * 1000,
    DELIVERY_TIMEOUT_MS,
    "src/api/policy.ts disagrees with src/notify/webhook.ts",
  );
  assert.equal(limits.deliveryTimeoutMs, DELIVERY_TIMEOUT_MS, "config/limits.json deliveryTimeoutMs disagrees");
});
BENCHEOF
